    # winding and disk guards once afterwards on the selected order.
    ends=g.node('GeometryNodeInputMeshEdgeVertices')
    delta=g.math('ABSOLUTE',c.V(g,ends.outputs['Vertex Index 1'])-c.V(g,ends.outputs['Vertex Index 2']))
    polar_valid=c._stat(g,wire,g.math('COMPARE',delta,1.)+g.math('COMPARE',delta,count-1.),domain='EDGE')
    ranked=c._store(g,wire,'_ip_polar_rank',index,'INT')
